// ─────────────────────────── индексы ───────────────────────────
const exact = new Map<string, OpeningInfo>();
const prefixes = new Set<string>();
const byEco = new Map<string, OpeningInfo>();
const catalog = new Map<string, OpeningCatalogEntry>();

export interface OpeningCatalogEntry extends OpeningInfo {
  moves: string;
  plyCount: number;
}

// ECO-подписи берём из локально выверенного словаря, затем дополняем Lichess.
for (const [eco, en, ru] of ROWS) if (!byEco.has(eco)) byEco.set(eco, { eco, en, ru });
for (const [eco, en, ru] of LICHESS_ROWS) if (!byEco.has(eco)) byEco.set(eco, { eco, en, ru });

// Импортированные линии индексируются первыми, а старые ручные записи идут последними
// и перекрывают их на совпадающих последовательностях.
for (const [eco, en, ru, moves] of [...LICHESS_ROWS, ...ROWS]) {
  const seq = moves.split(" ").filter(Boolean);
  const info = { eco, en, ru };
  const key = seq.join(" ");
  exact.set(key, info);
  for (let i = 1; i <= seq.length; i++) prefixes.add(seq.slice(0, i).join(" "));
  catalog.set(`${eco}|${key}`, { ...info, moves: key, plyCount: seq.length });
}

export function openingForCode(code: string): OpeningInfo | undefined {
  const c = code.toUpperCase().trim();
  if (!/^[A-E]\d\d$/.test(c)) return undefined;
  const known = byEco.get(c);
  if (known) return known;
  const family = FAMILIES.find(([from, to]) => c >= from && c <= to);
  return family ? { eco: c, en: family[2], ru: family[3] } : undefined;
}

/** Количество уникальных ECO-линий в доступном каталоге. */
export function openingCatalogCount(): number {
  return catalog.size;
}

/** Поиск по ECO, английскому/русскому названию и SAN-последовательности. */
export function searchOpenings(query = "", limit = 80): OpeningCatalogEntry[] {
  const q = query.trim().toLocaleLowerCase();
  const safeLimit = Math.max(1, Math.min(200, Math.floor(limit) || 80));
  const entries = Array.from(catalog.values());
  if (!q) return entries.slice(0, safeLimit);
  const matches = entries.filter((entry) =>
    entry.eco.toLowerCase().includes(q)
    || entry.en.toLocaleLowerCase().includes(q)
    || entry.ru.toLocaleLowerCase().includes(q)
    || entry.moves.toLocaleLowerCase().includes(q)
  );
  matches.sort((a, b) => {
    const aStarts = a.en.toLocaleLowerCase().startsWith(q) || a.ru.toLocaleLowerCase().startsWith(q) || a.eco.toLowerCase() === q;
    const bStarts = b.en.toLocaleLowerCase().startsWith(q) || b.ru.toLocaleLowerCase().startsWith(q) || b.eco.toLowerCase() === q;
    return Number(bStarts) - Number(aStarts) || b.plyCount - a.plyCount || a.en.localeCompare(b.en);
  });
  return matches.slice(0, safeLimit);
}

export interface BookInfo {
  isBook: boolean[];
  opening: (OpeningInfo | undefined)[]; // для каждого полухода — самое глубокое названное совпадение
  last?: OpeningInfo;
}

/** Размечает книжные ходы по списку SAN (без символов +/#). */
export function analyzeBook(sans: string[]): BookInfo {
  const clean = sans.map((s) => s.replace(/[+#!?]/g, ""));
  const isBook: boolean[] = [];
  const opening: (OpeningInfo | undefined)[] = [];
  let cur: OpeningInfo | undefined;
  let inBook = true;
  for (let i = 0; i < clean.length; i++) {
    const key = clean.slice(0, i + 1).join(" ");
    if (inBook && prefixes.has(key)) {
      isBook.push(true);
      const e = exact.get(key);
      if (e) cur = e;
    } else {
      inBook = false;
      isBook.push(false);
    }
    opening.push(cur);
  }
  return { isBook, opening, last: cur };
}
